sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    var method = request.httpMethod;
    try {
        var body;
        if (method === 'GET') {
            body = getList(request.queryParams);
        } else if (method === 'POST') {
            body = createRefund(request.body.data);
        } else {
            response.setStatus(405);
            return { success: false, error: 'Method not allowed' };
        }
        response.setStatus(body.success ? 200 : 400);
        return body;
    } catch (e) {
        response.setStatus(500);
        return { success: false, error: e.message };
    }

    function getList(qp) {
        var gr = new GlideRecord('x_2145749_qc_refund_request');
        if (qp.decision) gr.addQuery('decision', qp.decision);
        if (qp.case) gr.addQuery('case', qp.case);
        gr.orderByDesc('sys_created_on');
        var limit = parseInt(qp.limit, 10) || 50;
        var offset = parseInt(qp.offset, 10) || 0;
        gr.chooseWindow(offset, offset + limit);
        gr.query();
        var results = [];
        while (gr.next()) {
            results.push(toObj(gr));
        }
        return { success: true, result: results };
    }

    function createRefund(data) {
        if (!data || !data.case || !data.amount) {
            return { success: false, error: 'case and amount are required' };
        }
        var gr = new GlideRecord('x_2145749_qc_refund_request');
        gr.initialize();
        gr.setValue('case', data.case);
        gr.amount_requested = data.amount;
        gr.request_type = data.request_type || 'refund';
        gr.order_number = data.order_number || '';
        gr.customer = data.customer || gs.getUserID();
        // decision is intentionally left unset - existing ARE flows set it on insert/update
        var sysId = gr.insert();
        if (!sysId) {
            return { success: false, error: 'Insert failed' };
        }
        gr.get(sysId);
        return { success: true, result: toObj(gr) };
    }

    function toObj(gr) {
        var fraud = null;
        var fg = new GlideRecord('x_2145749_qc_fraud_flag');
        fg.addQuery('refund_request', gr.getUniqueValue());
        fg.query();
        if (fg.next()) {
            fraud = {
                risk_weight: fg.risk_weight.toString(),
                rule_name: fg.rule_name.toString(),
                details: fg.details.toString()
            };
        }
        return {
            sys_id: gr.getUniqueValue(),
            case: gr.getValue('case') ? gr.getDisplayValue('case') : '',
            amount_requested: gr.amount_requested.toString(),
            amount_approved: gr.amount_approved ? gr.amount_approved.toString() : null,
            decision: gr.decision.toString(),
            fraud_flag: fraud,
            created: gr.sys_created_on.toString()
        };
    }
})(request, response);
